def can_finish(num_courses: int, prerequisites: list[list[int]]) -> bool:
    # Create adjacency list for graph representation
    adj_list = [[] for _ in range(num_courses)]
    for course, prereq in prerequisites:
        adj_list[course].append(prereq)

    # Initialize visited array to keep track of visit states
    visited = [0] * num_courses  # 0=unvisited, 1=visiting, 2=visited

    def dfs(course):
        # If visiting this node again, we found a cycle
        if visited[course] == 1:
            return False
        # If already visited, no need to revisit
        if visited[course] == 2:
            return True

        # Mark as visiting
        visited[course] = 1

        # Visit all prerequisites
        for prereq in adj_list[course]:
            if not dfs(prereq):
                return False

        # Mark as visited after all prerequisites are processed
        visited[course] = 2
        return True

    # Check each course to ensure no cycles
    for course in range(num_courses):
        if not dfs(course):
            return False

    return True
